<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MIFECO Outreach Dashboard</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    /* === RESET & ROOT === */
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
    :root {
      --bg-primary: #0f172a;
      --bg-secondary: #1e293b;
      --bg-card: #1a2332;
      --border: #334155;
      --text-primary: #e2e8f0;
      --text-secondary: #94a3b8;
      --accent: #00ffcc;
      --accent-dim: rgba(0,255,204,0.12);
      --accent2: #667eea;
      --success: #22c55e;
      --warning: #f59e0b;
      --danger: #ef4444;
      --orange: #f97316;
      --info: #06b6d4;
      --purple: #8b5cf6;
      --sidebar-w: 220px;
      --shadow: 0 4px 24px rgba(0,0,0,0.3);
    }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
      display: flex;
      min-height: 100vh;
    }
    a { color: var(--accent); text-decoration: none; }
    a:hover { opacity: 0.85; }

    /* === SIDEBAR === */
    .sidebar {
      position: fixed;
      top: 0; left: 0;
      width: var(--sidebar-w);
      height: 100vh;
      background: #0a0f1a;
      border-right: 1px solid var(--border);
      display: flex;
      flex-direction: column;
      z-index: 100;
      overflow-y: auto;
    }
    .sidebar-logo {
      padding: 24px 20px 20px;
      border-bottom: 1px solid var(--border);
    }
    .sidebar-logo h1 {
      font-size: 16px;
      font-weight: 800;
      letter-spacing: 0.5px;
      color: var(--accent);
    }
    .sidebar-logo span {
      font-size: 10px;
      color: var(--text-secondary);
      letter-spacing: 2px;
      text-transform: uppercase;
    }
    .sidebar-nav { flex: 1; padding: 16px 0; }
    .sidebar-nav a {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 10px 20px;
      color: var(--text-secondary);
      font-size: 13px;
      font-weight: 500;
      transition: all 0.2s;
      border-left: 3px solid transparent;
    }
    .sidebar-nav a:hover, .sidebar-nav a.active {
      color: var(--text-primary);
      background: rgba(0,255,204,0.05);
      border-left-color: var(--accent);
    }
    .sidebar-nav a .icon { font-size: 16px; width: 20px; text-align: center; }
    .sidebar-footer {
      padding: 16px 20px;
      border-top: 1px solid var(--border);
      font-size: 11px;
    }
    .sidebar-footer a { color: var(--text-secondary); font-size: 11px; display: block; padding: 4px 0; }
    .sidebar-footer a:hover { color: var(--accent); }

    /* === MAIN CONTENT === */
    .main {
      margin-left: var(--sidebar-w);
      flex: 1;
      min-height: 100vh;
    }
    .container { max-width: 1200px; margin: 0 auto; padding: 28px 32px 40px; }

    /* === HEADER / STATS === */
    .hero {
      margin-bottom: 28px;
      animation: fadeIn 0.6s ease;
    }
    .hero h1 {
      font-size: 28px;
      font-weight: 800;
      background: linear-gradient(135deg, var(--text-primary), var(--accent));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .hero p {
      color: var(--text-secondary);
      font-size: 14px;
      margin-top: 2px;
      letter-spacing: 0.3px;
    }
    .stat-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      margin-top: 20px;
    }
    .stat-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 20px 24px;
      display: flex;
      align-items: center;
      gap: 16px;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .stat-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow);
    }
    .stat-card .stat-icon {
      width: 48px; height: 48px;
      border-radius: 12px;
      background: var(--accent-dim);
      display: flex; align-items: center; justify-content: center;
      font-size: 22px;
      flex-shrink: 0;
    }
    .stat-card .stat-content { flex: 1; }
    .stat-card .stat-number {
      font-size: 28px;
      font-weight: 700;
      color: var(--accent);
    }
    .stat-card .stat-label {
      font-size: 12px;
      color: var(--text-secondary);
      margin-top: 2px;
    }

    /* === LEAD GRID === */
    .leads-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 14px;
      margin-top: 24px;
    }

    /* === LEAD CARD === */
    .lead-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 20px 24px;
      display: flex;
      flex-wrap: wrap;
      align-items: flex-start;
      gap: 16px;
      transition: all 0.3s ease;
      animation: fadeIn 0.4s ease;
      position: relative;
      overflow: hidden;
    }
    .lead-card:hover {
      border-color: rgba(0,255,204,0.3);
      box-shadow: 0 4px 20px rgba(0,0,0,0.3);
    }
    .lead-card.deleted {
      animation: slideOut 0.4s ease forwards;
    }
    .lead-card.sent-overlay::after {
      content: '✓ Sent';
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: rgba(34,197,94,0.12);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
      font-weight: 800;
      color: var(--success);
      pointer-events: none;
      border-radius: 12px;
      backdrop-filter: blur(2px);
      z-index: 10;
    }

    .lead-card .lc-left {
      display: flex;
      flex-direction: column;
      gap: 6px;
      flex: 1;
      min-width: 200px;
    }
    .lead-card .lc-pipeline {
      display: inline-block;
      font-size: 10px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      padding: 3px 10px;
      border-radius: 20px;
      width: fit-content;
    }
    .lc-pipeline.books { background: #3b82f633; color: #3b82f6; }
    .lc-pipeline.saas { background: #06b6d433; color: #06b6d4; }
    .lc-pipeline.consulting { background: #8b5cf633; color: #8b5cf6; }

    .lead-card .lc-name {
      font-size: 16px;
      font-weight: 700;
      color: var(--text-primary);
    }
    .lead-card .lc-company {
      font-size: 13px;
      color: var(--text-secondary);
      font-weight: 500;
    }
    .lead-card .lc-enriched {
      display: flex;
      flex-direction: column;
      gap: 4px;
      margin-top: 6px;
    }
    .lead-card .lc-enriched-item {
      font-size: 12px;
      color: var(--text-secondary);
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .lead-card .lc-enriched-item .lc-label {
      color: var(--text-secondary);
