    /* === ANIMATIONS === */
    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }
    @keyframes slideOut {
      from { opacity: 1; transform: translateX(0); max-height: 300px; margin-bottom: 14px; padding: 20px 24px; }
      to { opacity: 0; transform: translateX(80px); max-height: 0; margin-bottom: 0; padding: 0 24px; }
    }
    @keyframes pulseStat {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.75; }
    }

    @media (max-width: 900px) {
      .hamburger { display: block; }
      .overlay.open { display: block; }
      .sidebar {
        transform: translateX(-100%);
        transition: transform 0.3s ease;
