<script>
// ===== LEAD DATA =====
const LEADS = [
  // BOOKS (7 leads)
  { id:'l1', pipeline:'Books', name:'Rev. Angela Torres', company:'Hope Fellowship', email:'atorres@hopefellowship.org', linkedin:'linkedin.com/in/angelatorres', score:45, stage:'Email Ready', enriched:true, notes:'30 copies of Tomorrow Remembered - $599.70' },
