  { id:'l16', pipeline:'Books', name:'Pastor Michael Reeves', company:'Riverside Church', email:'', linkedin:'linkedin.com/in/michaelreeves', score:29, stage:'LinkedIn Draft', enriched:false, notes:'Book club inquiry - no email on file' },
  { id:'l19', pipeline:'Books', name:'Dr. Sarah Chen', company:'Cornerstone Seminary', email:'schen@cornerstonesem.edu', linkedin:'linkedin.com/in/sarahchen', score:48, stage:'Email Ready', enriched:true, notes:'Faculty adoption: 3 textbooks per semester - $2,400/yr' },

  // SAAS (8 leads)
  { id:'l2', pipeline:'SaaS', name:'Dr. Amara Osei', company:'HealthBridge Tech', email:'aosei@healthbridge.tech', linkedin:'linkedin.com/in/amaraosei', score:37, stage:'Email Ready', enriched:true, notes:'Project Hypatia Pro - Score 37/50' },
  { id:'l5', pipeline:'SaaS', name:'Tom Reynolds', company:'DataStream Analytics', email:'treynolds@datastream.io', linkedin:'linkedin.com/in/tomreynolds', score:44, stage:'Email Ready', enriched:true, notes:'Enterprise plan - 250 users - $24,000/yr' },
  { id:'l8', pipeline:'SaaS', name:'Priya Patel', company:'MedRecord Systems', email:'', linkedin:'linkedin.com/in/priyapatel', score:31, stage:'LinkedIn Draft', enriched:false, notes:'Interested in compliance module - needs email' },
  { id:'l11', pipeline:'SaaS', name:'Alex Nakamura', company:'CloudForge Inc.', email:'anakamura@cloudforge.dev', linkedin:'linkedin.com/in/alexnakamura', score:39, stage:'Email Ready', enriched:true, notes:'DevOps platform trial - 50 seats - $6,000/yr' },
  { id:'l14', pipeline:'SaaS', name:'Dr. Lisa Park', company:'BioGenix Labs', email:'', linkedin:'linkedin.com/in/lisapark', score:34, stage:'LinkedIn Draft', enriched:false, notes:'Research data platform demo requested - no email' },
  { id:'l17', pipeline:'SaaS', name:'Marcus Webb', company:'FinFlow Capital', email:'mwebb@finflowcap.com', linkedin:'linkedin.com/in/marcuswebb', score:41, stage:'Email Ready', enriched:true, notes:'AI analytics suite - 100 users - $18,000/yr' },
  { id:'l20', pipeline:'SaaS', name:'Rachel Torres', company:'EduSpark Learning', email:'rtorres@eduspark.io', linkedin:'linkedin.com/in/racheltorres', score:36, stage:'Email Ready', enriched:true, notes:'Student LMS integration - pilot - $3,600/yr' },
  { id:'l22', pipeline:'SaaS', name:'Dr. Kenji Yamamoto', company:'Quantum Research', email:'', linkedin:'linkedin.com/in/kenjiyamamoto', score:30, stage:'LinkedIn Draft', enriched:false, notes:'HPC cluster management - needs contact email' },

  // CONSULTING (8 leads)
  { id:'l3', pipeline:'Consulting', name:'Marcus Chen', company:'Collective Health', email:'', linkedin:'linkedin.com/in/marcuschen', score:28, stage:'LinkedIn Draft', enriched:false, notes:'AI Readiness Consulting - $199-$3,999 - needs email' },
  { id:'l6', pipeline:'Consulting', name:'Julia Hartwell', company:'Hartwell & Co.', email:'jhartwell@hartwellco.com', linkedin:'linkedin.com/in/juliahartwell', score:35, stage:'Email Ready', enriched:true, notes:'Digital transformation strategy - Tier 2 - $1,999' },
  { id:'l9', pipeline:'Consulting', name:'Dr. Omar Hassan', company:'Global Health Initiative', email:'ohassan@globalhealth.org', linkedin:'linkedin.com/in/omarhassan', score:43, stage:'Email Ready', enriched:true, notes:'AI readiness assessment for 3 departments - $5,997' },
  { id:'l12', pipeline:'Consulting', name:'Samantha Blake', company:'Blake Strategies', email:'', linkedin:'linkedin.com/in/samanthablake', score:26, stage:'LinkedIn Draft', enriched:false, notes:'Fractional CTO consulting - needs email address' },
  { id:'l15', pipeline:'Consulting', name:'Robert Okafor', company:'AfriTech Ventures', email:'rokafor@afritech.ventures', linkedin:'linkedin.com/in/robertokafor', score:47, stage:'Email Ready', enriched:true, notes:'Full consulting engagement - Tier 3 - $3,999' },
  { id:'l18', pipeline:'Consulting', name:'Dr. Elena Vasquez', company:'Vasquez Medical Group', email:'evasquez@vasquezmed.com', linkedin:'linkedin.com/in/elenavasquez', score:38, stage:'Email Ready', enriched:true, notes:'AI workflow optimization - Specialty practice - $2,499' },
  { id:'l21', pipeline:'Consulting', name:'Nathan Cross', company:'CrossFit Franchise HQ', email:'', linkedin:'linkedin.com/in/nathancross', score:22, stage:'LinkedIn Draft', enriched:false, notes:'Operational AI consulting - needs email contact' },
  { id:'l23', pipeline:'Consulting', name:'Dr. Fiona MacAllister', company:'MacAllister Biotech', email:'fmac@macbiotech.co.uk', linkedin:'linkedin.com/in/fionamacallister', score:49, stage:'Email Ready', enriched:true, notes:'Strategic AI transformation - Full engagement - $5,500' }
];

// ===== STATE =====
let sentIds = [];
let deletedIds = [];
let currentAction = null;
let currentLeadId = null;
let currentFilter = 'all';

// ===== INIT =====
document.addEventListener('DOMContentLoaded', function() {
  // Load persisted state
  try {
    const storedSent = localStorage.getItem('outreach-sent');
    const storedDeleted = localStorage.getItem('outreach-deleted');
    if (storedSent) sentIds = JSON.parse(storedSent);
    if (storedDeleted) deletedIds = JSON.parse(storedDeleted);
  } catch(e) {
    sentIds = [];
    deletedIds = [];
  }

  renderLeads();
  updateStats();
});

// ===== RENDER =====
function renderLeads() {
  const grid = document.getElementById('leadsGrid');
  grid.innerHTML = '';

  const filtered = getFilteredLeads();
  let count = 0;

  filtered.forEach(lead => {
    if (deletedIds.includes(lead.id)) return;
    count++;
    const card = createLeadCard(lead);
    grid.appendChild(card);
  });

  document.getElementById('filterCount').textContent = `Showing ${count} of ${getVisibleLeadCount()}`;
  updateStats();
}

function getVisibleLeadCount() {
  let total = 0;
  LEADS.forEach(l => { if (!deletedIds.includes(l.id)) total++; });
  return total;
}

function getFilteredLeads() {
  let filtered = LEADS.filter(l => !deletedIds.includes(l.id));
  if (currentFilter === 'all') return filtered;
  if (currentFilter === 'ready') return filtered.filter(l => isValidEmail(l.email));
  if (currentFilter === 'needs') return filtered.filter(l => !isValidEmail(l.email));
  return filtered.filter(l => l.pipeline === currentFilter);
}

function isValidEmail(email) {
  if (!email || typeof email !== 'string') return false;
  const parts = email.split('@');
  if (parts.length !== 2) return false;
  const domain = parts[1];
  if (!domain || !domain.includes('.')) return false;
  return domain.split('.').every(part => part.length > 0);
}

function createLeadCard(lead) {
  const card = document.createElement('div');
  card.className = 'lead-card';
  card.id = 'card-' + lead.id;
  if (sentIds.includes(lead.id)) {
    card.classList.add('sent-overlay');
  }

  const pipelineClass = lead.pipeline.toLowerCase();
  const isReady = isValidEmail(lead.email);
  const isSent = sentIds.includes(lead.id);

  let actionHtml = '';
  if (isSent) {
    actionHtml = `<button class="btn btn-primary" disabled>✓ Sent</button>`;
  } else if (isReady) {
    const btnText = '📤 Send Email';
    actionHtml = `<button class="btn btn-primary" onclick="openSendModal('${lead.id}')">${btnText}</button>`;
  } else {
    actionHtml = `<span class="enrich-warning">⚠️ Needs Enrichment — no valid email</span>`;
  }

  const emailDisplay = isReady ? lead.email : '<span style="color:var(--danger)">— no email —</span>';
  const linkedinUrl = lead.linkedin ? (lead.linkedin.startsWith('http') ? lead.linkedin : 'https://' + lead.linkedin) : '';
  const linkedinDisplay = lead.linkedin ? `<a href="${linkedinUrl}" target="_blank">${lead.linkedin}</a>` : '—';

  const stageClass = lead.stage.includes('Ready') ? 'ready' : lead.stage.includes('Draft') ? 'draft' : 'qualified';

  card.innerHTML = `
    <div class="lc-left">
      <div class="lc-pipeline ${pipelineClass}">${lead.pipeline}</div>
      <div class="lc-name">${lead.name}</div>
      <div class="lc-company">${lead.company}</div>
      <div class="lc-enriched">
        <div class="lc-enriched-item">
          <span class="lc-label">📧 Email:</span>
          <span class="lc-value">${emailDisplay}</span>
        </div>
        <div class="lc-enriched-item">
          <span class="lc-label">🔗 LinkedIn:</span>
          <span class="lc-value">${linkedinDisplay}</span>
        </div>
      </div>
    </div>
    <div class="lc-right">
      <div class="lc-score">
        <span class="score-num">${lead.score}</span>
        <span class="score-label">/50<br>Score</span>
      </div>
      <div class="lc-stage ${stageClass}">${lead.stage}</div>
      <div class="lc-actions">
        ${actionHtml}
        <button class="btn btn-danger" onclick="openDeleteModal('${lead.id}')">🗑</button>
      </div>
    </div>
    <div class="lc-notes">
      <span class="notes-icon">📝</span>
      <span>${lead.notes}</span>
    </div>
  `;

  return card;
}

// ===== FILTER =====
function filterLeads(filter) {
  currentFilter = filter;
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.filter === filter);
  });
  renderLeads();
}

// ===== STATS =====
function updateStats() {
  const visible = LEADS.filter(l => !deletedIds.includes(l.id));
  const qualified = visible.filter(l => isValidEmail(l.email));
  document.getElementById('totalLeads').textContent = visible.length;
  document.getElementById('qualifiedLeads').textContent = qualified.length;
}

// ===== MODAL =====
function openSendModal(leadId) {
  const lead = LEADS.find(l => l.id === leadId);
  if (!lead) return;
  currentAction = 'send';
  currentLeadId = leadId;
  document.getElementById('modalTitle').textContent = '📤 Confirm Send';
  document.getElementById('modalMessage').innerHTML = `Send outreach email to <strong>${lead.name}</strong> at <strong>${lead.email}</strong>?<br><br><span style="color:var(--text-secondary);font-size:12px;">${lead.notes}</span>`;
  const btn = document.getElementById('modalConfirmBtn');
  btn.textContent = '📤 Send Email';
  btn.className = 'btn btn-confirm';
  document.getElementById('confirmModal').classList.add('show');
}

function openDeleteModal(leadId) {
  const lead = LEADS.find(l => l.id === leadId);
  if (!lead) return;
  currentAction = 'delete';
  currentLeadId = leadId;
  document.getElementById('modalTitle').textContent = '🗑 Confirm Delete';
  document.getElementById('modalMessage').innerHTML = `Remove <strong>${lead.name}</strong> from <strong>${lead.company}</strong>?<br><br><span style="color:var(--text-secondary);font-size:12px;">This cannot be undone, but the card will be hidden from this view.</span>`;
  const btn = document.getElementById('modalConfirmBtn');
  btn.textContent = '🗑 Delete';
  btn.className = 'btn btn-confirm-del';
  document.getElementById('confirmModal').classList.add('show');
}

function closeModal() {
  document.getElementById('confirmModal').classList.remove('show');
  currentAction = null;
  currentLeadId = null;
}

function executeAction() {
  if (currentAction === 'send' && currentLeadId) {
    if (!sentIds.includes(currentLeadId)) {
      sentIds.push(currentLeadId);
      localStorage.setItem('outreach-sent', JSON.stringify(sentIds));
    }
    renderLeads();
    updateStats();
  } else if (currentAction === 'delete' && currentLeadId) {
    if (!deletedIds.includes(currentLeadId)) {
      deletedIds.push(currentLeadId);
      localStorage.setItem('outreach-deleted', JSON.stringify(deletedIds));
    }
    const card = document.getElementById('card-' + currentLeadId);
    if (card) {
      card.classList.add('deleted');
      setTimeout(() => {
        renderLeads();
        updateStats();
      }, 420);
    } else {
      renderLeads();
      updateStats();
    }
  }
  closeModal();
}

// ===== SIDEBAR TOGGLE =====
function toggleSidebar() {
  document.getElementById('sidebar').classList.toggle('open');
  document.getElementById('overlay').classList.toggle('open');
}
function closeSidebar() {
  document.getElementById('sidebar').classList.remove('open');
  document.getElementById('overlay').classList.remove('open');
}
</script>

</body>
</html>
